package nvt.vn.ute_forum.repository;

import nvt.vn.ute_forum.model.FileAttachment;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Repository;

@Repository
public interface FileAttachmentRepo extends JpaRepository<FileAttachment, String> {
	@Query(value = "SELECT COALESCE(MAX(CAST(SUBSTRING(id, 4) AS UNSIGNED)), 0) FROM fileattachment WHERE id REGEXP '^FA_[0-9]+$'", nativeQuery = true)
	Long findMaxFileAttachmentSequence();
}

package nvt.vn.ute_forum.repository;

import nvt.vn.ute_forum.model.Request;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

import java.util.List;

@Repository
public interface RequestRepo extends JpaRepository<Request, String> {
    List<Request> findByUser_IdOrderByTimeCreateDesc(String userId);
    Optional<Request> findByIdAndUser_Id(String id, String userId);
    // Thêm Pageable vào đây và đổi kiểu trả về thành Page<Request>
    Page<Request> findByPostStatus(String status, Pageable pageable);

    @Query("SELECT DISTINCT r FROM Request r " +
            "LEFT JOIN r.categories c " +
            "WHERE r.postStatus = 'PUBLIC' " +
            // Nếu :categoryId là null, điều kiện này luôn đúng (lấy tất cả)
            "AND (:categoryId IS NULL OR c.id = :categoryId) " +
            // Nếu :departmentId là null, điều kiện này luôn đúng (lấy tất cả)
            "AND (:departmentId IS NULL OR r.department.id = :departmentId) " +
            "ORDER BY " +
            "CASE WHEN :sortBy = 'newest' THEN r.timeCreate END DESC, " +
            "CASE WHEN :sortBy = 'oldest' THEN r.timeCreate END ASC")
    List<Request> findByFilters(
            @Param("categoryId") String categoryId,
            @Param("departmentId") String departmentId,
            @Param("sortBy") String sortBy
    );




}

package nvt.vn.ute_forum.repository;

import nvt.vn.ute_forum.model.Request;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

@Repository
public interface RequestRepo extends JpaRepository<Request, String> {
    List<Request> findByUser_IdOrderByTimeCreateDesc(String userId);
    Optional<Request> findByIdAndUser_Id(String id, String userId);
    // Thêm Pageable vào đây và đổi kiểu trả về thành Page<Request>
    Page<Request> findByPostStatus(String status, Pageable pageable);

    @Query("SELECT DISTINCT r FROM Request r " +
            "LEFT JOIN r.categories c " +
            "WHERE r.postStatus = 'PUBLIC' " +
            // Nếu :categoryId là null, điều kiện này luôn đúng (lấy tất cả)
            "AND (:categoryId IS NULL OR c.id = :categoryId) " +
            // Nếu :departmentId là null, điều kiện này luôn đúng (lấy tất cả)
            "AND (:departmentId IS NULL OR r.department.id = :departmentId) " +
            "ORDER BY " +
            "CASE WHEN :sortBy = 'newest' THEN r.timeCreate END DESC, " +
            "CASE WHEN :sortBy = 'oldest' THEN r.timeCreate END ASC")
    List<Request> findByFilters(
            @Param("categoryId") String categoryId,
            @Param("departmentId") String departmentId,
            @Param("sortBy") String sortBy
    );

    @Query(value = "SELECT COALESCE(MAX(CAST(SUBSTRING(id, 5) AS UNSIGNED)), 0) FROM request WHERE id REGEXP '^REQ_[0-9]+$'", nativeQuery = true)
    Long findMaxRequestSequence();




}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.model.FileAttachment;
import nvt.vn.ute_forum.model.Request;
import nvt.vn.ute_forum.repository.FileAttachmentRepo;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.time.LocalDate;

@Service
public class FileAttachmentService {

    @Autowired
    private FileAttachmentRepo fileAttachmentRepo;

    @Value("${app.upload.dir:uploads/}")
    private String uploadDir;

    public void saveRequestAttachments(Request request, MultipartFile[] attachments) throws IOException {
        if (request == null || request.getId() == null || attachments == null || attachments.length == 0) {
            return;
        }

        Path uploadRoot = Paths.get(uploadDir).toAbsolutePath().normalize();
        Files.createDirectories(uploadRoot);

        for (MultipartFile file : attachments) {
            if (file == null || file.isEmpty()) {
                continue;
            }

            String originalName = file.getOriginalFilename() == null ? "file" : Paths.get(file.getOriginalFilename()).getFileName().toString();
            String extension = "";
            int dotIndex = originalName.lastIndexOf('.');
            if (dotIndex >= 0) {
                extension = originalName.substring(dotIndex);
            }

            String storedFileName = request.getId() + "_" + System.nanoTime() + extension;
            Path target = uploadRoot.resolve(storedFileName);
            Files.copy(file.getInputStream(), target, StandardCopyOption.REPLACE_EXISTING);

            FileAttachment attachment = new FileAttachment();
            attachment.setId("FA_" + System.nanoTime());
            attachment.setFileName(originalName);
            attachment.setFileType(file.getContentType());
            attachment.setFileSize((int) Math.min(file.getSize(), Integer.MAX_VALUE));
            attachment.setCreateAt(LocalDate.now());
            attachment.setFileUrl("/uploads/" + storedFileName);
            attachment.setRequest(request);

            fileAttachmentRepo.save(attachment);
        }
    }

}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.model.FileAttachment;
import nvt.vn.ute_forum.model.Request;
import nvt.vn.ute_forum.repository.FileAttachmentRepo;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.time.LocalDate;

@Service
public class FileAttachmentService {

    @Autowired
    private FileAttachmentRepo fileAttachmentRepo;

    @Autowired
    private IdGeneratorService idGeneratorService;

    @Value("${app.upload.dir:uploads/}")
    private String uploadDir;

    public void saveRequestAttachments(Request request, MultipartFile[] attachments) throws IOException {
        if (request == null || request.getId() == null || attachments == null || attachments.length == 0) {
            return;
        }

        Path uploadRoot = Paths.get(uploadDir).toAbsolutePath().normalize();
        Files.createDirectories(uploadRoot);

        for (MultipartFile file : attachments) {
            if (file == null || file.isEmpty()) {
                continue;
            }

            String originalName = file.getOriginalFilename() == null ? "file" : Paths.get(file.getOriginalFilename()).getFileName().toString();
            String extension = "";
            int dotIndex = originalName.lastIndexOf('.');
            if (dotIndex >= 0) {
                extension = originalName.substring(dotIndex);
            }

            String storedFileName = request.getId() + "_" + System.nanoTime() + extension;
            Path target = uploadRoot.resolve(storedFileName);
            Files.copy(file.getInputStream(), target, StandardCopyOption.REPLACE_EXISTING);

            FileAttachment attachment = new FileAttachment();
            attachment.setId(idGeneratorService.nextFileAttachmentId());
            attachment.setFileName(originalName);
            attachment.setFileType(file.getContentType());
            attachment.setFileSize((int) Math.min(file.getSize(), Integer.MAX_VALUE));
            attachment.setCreateAt(LocalDate.now());
            attachment.setFileUrl("/uploads/" + storedFileName);
            attachment.setRequest(request);

            fileAttachmentRepo.save(attachment);
        }
    }

}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.repository.FileAttachmentRepo;
import nvt.vn.ute_forum.repository.RequestRepo;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class IdGeneratorService {

    private final RequestRepo requestRepo;
    private final FileAttachmentRepo fileAttachmentRepo;

    private long requestSequence = -1;
    private long fileAttachmentSequence = -1;

    public IdGeneratorService(RequestRepo requestRepo, FileAttachmentRepo fileAttachmentRepo) {
        this.requestRepo = requestRepo;
        this.fileAttachmentRepo = fileAttachmentRepo;
    }

    @Transactional(readOnly = true)
    public synchronized String nextRequestId() {
        if (requestSequence < 0) {
            requestSequence = safeSequence(requestRepo.findMaxRequestSequence());
        }
        requestSequence++;
        return "REQ_" + requestSequence;
    }

    @Transactional(readOnly = true)
    public synchronized String nextFileAttachmentId() {
        if (fileAttachmentSequence < 0) {
            fileAttachmentSequence = safeSequence(fileAttachmentRepo.findMaxFileAttachmentSequence());
        }
        fileAttachmentSequence++;
        return "FA_" + fileAttachmentSequence;
    }

    private long safeSequence(Long value) {
        return value == null ? 0L : value;
    }
}
